const input = items[0].json.body;

const thread = input.thread || [];
const prompt = input.prompt || "";
const channel = (input.channel || "email").toLowerCase();
const language = input.language || "English";
const lead = input.lead || {};

const customerName = (lead.name || "").trim();

// 1. Sort thread
thread.sort((a, b) => new Date(a.date) - new Date(b.date));

// 2. Build conversation (last 6 messages)
let conversation = thread.slice(-6).map(msg => {
  const role = msg.direction === "IN" ? "Customer" : "Agent";
  const body = (msg.body || "").replace(/\s+/g, " ").trim();
  return `${role}: ${body}`;
}).join("\n");

// 3. Lead context
const leadContext = `
Customer Name: ${customerName}
Vehicle Interest: ${lead.vehicle_year || ""} ${lead.vehicle_make || ""} ${lead.vehicle_model || ""}
Dealer: ${input.dealerName || ""}
`;

// 4. Name instruction (critical layer)
let nameInstruction = "";

if (customerName) {
  nameInstruction = `
- ALWAYS address the customer by name: "${customerName}"
- For SMS: Start with the name (e.g., "Abhay, ...")
- For Email: Use proper greeting (e.g., "Hi Abhay,")
`;
} else {
  nameInstruction = `
- Do NOT assume or invent a name
- Use generic greeting if needed
`;
}

// 5. Channel rules
let channelInstruction = "";
let useContext = true;

if (channel === "sms") {
  channelInstruction = `
- Response MUST be under 160 characters
- Keep it concise and action-oriented
- No signatures
`;
} else if (channel === "email") {
  channelInstruction = `
- Write a structured, professional email
- Include greeting and closing
- Encourage next step (appointment/test drive)
`;
} else if (channel === "notes") {
  channelInstruction = `
- Internal note only
- No greeting, no customer-facing tone
- Summarize intent + next action
`;
  useContext = false;
}

// 6. Final prompt
let finalPrompt;

if (useContext && conversation) {
  finalPrompt = `
You are an expert dealership sales assistant.

Language: ${language}

Customer Context:
${leadContext}

Conversation so far:
${conversation}

Instruction:
${prompt}

Name Personalization Rules:
${nameInstruction}

Channel Rules:
${channelInstruction}

Goal:
- Be natural and human
- Move toward appointment booking
`;
} else {
  finalPrompt = `
You are an expert dealership assistant.

Language: ${language}

Context:
${leadContext}

Instruction:
${prompt}

Name Personalization Rules:
${nameInstruction}

Channel Rules:
${channelInstruction}
`;
}

// 7. Output
return [{
  json: {
    finalPrompt,
    channel,
    language,
    customerName
  }
}];

let raw = items[0].json.output?.[0]?.content?.[0]?.text || "";

// Extract JSON safely (handles extra text if model misbehaves)
const match = raw.match(/\{[\s\S]*\}/);

let parsed;

try {
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = {
    draft: raw,
    subject: "",
    name: ""
  };
}

return [{
  json: {
    draft: parsed.draft || "",
    subject: parsed.subject || "",
    name: parsed.name || ""
  }
}];
